## Code Example

```c
static inline unsigned parity128(uint128 x) {
  uint64_t lo = x.lo;
  lo ^= lo >> 32;
  lo ^= lo >> 16;
  lo ^= lo >> 8;
  lo ^= lo >> 4;
  lo ^= lo >> 2;
  lo ^= lo >> 1;
  uint64_t hi = x.hi;
  hi ^= hi >> 32;
  hi ^= hi >> 16;
  hi ^= hi >> 8;
  hi ^= hi >> 4;
  hi ^= hi >> 2;
  hi ^= hi >> 1;
  return (lo & 1) ^ (hi & 1);
}
```

